  --animate-action-download: action-download 540ms var(--ease-out) both;
  --animate-action-archive: action-archive 520ms var(--ease-out) both;
  --animate-action-bell: action-bell 680ms var(--ease-out) both;
  --animate-action-settings: action-settings 720ms var(--ease-out) both;
}

/* Named motion tracks are part of the public styling contract. */
@keyframes marquee { to { transform: translateX(calc(-100% - var(--gap, 1rem))); } }
@keyframes marquee-vertical { to { transform: translateY(calc(-100% - var(--gap, 1rem))); } }
@keyframes rainbow-border {
  from { background-position: 0% 50%; }
  to { background-position: 100% 50%; }
}
@keyframes shimmer {
  from { background-position: 200% 0; }
  to { background-position: -200% 0; }
}
@keyframes action-send {
  0%, 100% { transform: translate(0, 0); }
  45% { transform: translate(2px, -2px); }
}
@keyframes action-copy {
  0%, 100% { transform: translate(0, 0); }
  40% { transform: translate(1.5px, -1.5px); }
  70% { transform: translate(-1px, 1px); }
}
@keyframes action-download {
  0%, 100% { transform: translateY(0); }
  42% { transform: translateY(2.5px); }
}
@keyframes action-archive {
  0%, 100% { transform: scale(1); }
  45% { transform: scale(0.9); }
}
@keyframes action-bell {
  0%, 100% { transform: rotate(0deg); }
  18% { transform: rotate(14deg); }
  36% { transform: rotate(-12deg); }
  54% { transform: rotate(8deg); }
  72% { transform: rotate(-5deg); }
}
@keyframes action-settings {
  from { transform: rotate(0deg); }
  to { transform: rotate(90deg); }
}

@layer base {
  html, body { overflow-x: clip; }
  html { color-scheme: light dark; }
  body {
    font-family: var(--font-sans);
    color: var(--foreground);
    background: var(--background);
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
  }
  a, button:not(:disabled), [role="button"]:not(:disabled) { cursor: pointer; }
  ::selection {
    color: var(--foreground);
    background: color-mix(in oklch, var(--accent) 30%, transparent);
  }
  .shiki, .shiki span { color: var(--shiki-light); }
  .dark .shiki, .dark .shiki span { color: var(--shiki-dark); }
}

@layer utilities {
  .text-balance { text-wrap: balance; }
  .text-pretty { text-wrap: pretty; }
  .scrollbar-hide { scrollbar-width: none; }
  .scrollbar-hide::-webkit-scrollbar { display: none; }
  .mask-b-fade { mask-image: linear-gradient(to bottom, black 60%, transparent); }
  .mask-radial-fade { mask-image: radial-gradient(ellipse at center, black 40%, transparent 75%); }
  .grid-noise {
    background-size: 32px 32px;
    background-image: linear-gradient(to right, color-mix(in oklch, var(--foreground) 6%, transparent) 1px, transparent 1px), linear-gradient(to bottom, color-mix(in oklch, var(--foreground) 6%, transparent) 1px, transparent 1px);
  }
  .glass {
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    backdrop-filter: blur(20px) saturate(160%);
    box-shadow: inset 0 1px 0 0 rgb(255 255 255 / 0.06), 0 24px 60px -24px rgb(0 0 0 / 0.45);
  }
  .glass-strong { background: var(--glass-strong-bg); backdrop-filter: blur(16px); }
  .glass-thin { background: var(--glass-thin-bg); backdrop-filter: blur(12px); border: 1px solid var(--glass-border); }
  .press { transition: transform 120ms var(--ease-out); }
  .press:active { transform: scale(0.97); }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

